Object.assign(translations.ja,{
 chooseLanguage:'言語を選ぶ',navLabel:'メインナビゲーション',projectFilterLabel:'プロジェクトの絞り込み',flowLabel:'システムの流れ',rawLS:'未処理 LS',rawWLS:'未処理 WLS',
 channel5:'5タップチャネル',channel3:'3タップチャネル',channel2:'2タップチャネル',
 chartReading:'{channel}・0 dB：平均軌跡RMSE {ls} Hz → {wls} Hz。',docTitle:'Somesh Mridha — エンジニアリングポートフォリオ'
});
for(const [code,locale] of Object.entries(additionalLanguages)){
 translations[code]=locale.labels;
 for(const id of ['research','motor','energy']){
  cases[id][code]=locale.cases[id];
  portfolioEvidence.parameters[id][code]=locale.parameters[id];
  portfolioEvidence.decisions[id][code]=locale.decisions[id];
  portfolioEvidence.galleries[id].forEach((figure,index)=>figure[code]=locale.galleries[id][index]);
 }
}

let language='en',currentCase=null;
const $=selector=>document.querySelector(selector);
const escapeHTML=value=>String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
function setLanguage(next){
 language=supportedLanguages.includes(next)?next:'en';
 const t=translations[language];
 document.documentElement.lang=language;
 document.title=t.docTitle;
 document.querySelectorAll('[data-i18n]').forEach(el=>{const value=t[el.dataset.i18n];if(value!==undefined)el.textContent=value;});
 document.querySelectorAll('[data-i18n-aria]').forEach(el=>el.setAttribute('aria-label',t[el.dataset.i18nAria]));
 document.querySelectorAll('[data-language-select]').forEach(select=>{select.value=language;select.setAttribute('aria-label',t.chooseLanguage);});
 $('#close-dialog').setAttribute('aria-label',t.closeCase);
 $('#results-chart').setAttribute('aria-label',t.chartDesc);
 Array.from($('#channel').options).forEach((option,i)=>option.textContent=[t.channel5,t.channel3,t.channel2][i]);
 const figureByFile=Object.values(portfolioEvidence.galleries).flat();
 document.querySelectorAll('img[src*="assets/evidence/"]').forEach(img=>{
  const figure=figureByFile.find(f=>img.getAttribute('src').endsWith('/'+f.file));
  if(figure)img.alt=figure[language][0]+' — '+figure[language][1];
 });
 $('#copy-status').textContent='';
 try{localStorage.setItem('somesh-portfolio-language',language);}catch{}
 renderChart();
 if(currentCase){renderCase(currentCase);$('#case-dialog').scrollTop=0;}
}
function renderChart(){
 const {ls,wls}=resultData[$('#channel').value];const plot=$('#results-chart');
 const x=i=>48+i*96,y=v=>231-v/65*205;
 let markup=`<title>${escapeHTML(translations[language].chartTitle)}</title><desc>${escapeHTML(translations[language].chartDesc)}</desc>`;
 [0,20,40,60].forEach(tick=>{markup+=`<line x1="48" y1="${y(tick)}" x2="528" y2="${y(tick)}" stroke="#bccab5" stroke-width=".7"/><text x="32" y="${y(tick)+3}" fill="#60745c" text-anchor="end" font-family="Consolas,monospace" font-size="10">${tick}</text>`;});
 snr.forEach((value,i)=>{markup+=`<text x="${x(i)}" y="251" text-anchor="middle" fill="#60745c" font-family="Consolas,monospace" font-size="10">${value}</text>`;});
 markup+=`<text x="528" y="275" text-anchor="end" fill="#60745c" font-family="Consolas,monospace" font-size="9">${escapeHTML(translations[language].chartX)}</text>`;
 [[ls,'#7a8b72',translations[language].rawLS,'5 4'],[wls,'#aa532e',translations[language].rawWLS,'']].forEach(([values,color,label,dash])=>{
  markup+=`<path d="${values.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ')}" fill="none" stroke="${color}" stroke-width="2" stroke-dasharray="${dash}"/>`;
  values.forEach((value,i)=>{markup+=`<circle cx="${x(i)}" cy="${y(value)}" r="3.5" fill="${color}" stroke="#e3e9dc" stroke-width="1.5"><title>${label}: ${snr[i]} dB, ${value.toFixed(3)} Hz</title></circle>`;});
 });
 plot.innerHTML=markup;plot.removeAttribute('aria-labelledby');
 const channel=$('#channel').selectedOptions[0].textContent;
 $('#chart-reading').textContent=translations[language].chartReading.replace('{channel}',channel).replace('{ls}',ls[0].toFixed(3)).replace('{wls}',wls[0].toFixed(3));
}
function renderEvidence(id){
 const t=translations[language],e=portfolioEvidence;
 let html=`<section class="case-block"><h3>${escapeHTML(t.parametersTitle)}</h3><div class="data-table-wrap"><table class="parameter-table"><thead><tr><th scope="col">${escapeHTML(t.parameter)}</th><th scope="col">${escapeHTML(t.value)}</th></tr></thead><tbody>${e.parameters[id][language].map(([key,value])=>`<tr><th scope="row">${escapeHTML(key)}</th><td>${escapeHTML(value)}</td></tr>`).join('')}</tbody></table></div></section>`;
 html+=`<section class="case-block case-decisions"><h3>${escapeHTML(t.decisionsTitle)}</h3>${e.decisions[id][language].map(([heading,text])=>`<div><h4>${escapeHTML(heading)}</h4><p>${escapeHTML(text)}</p></div>`).join('')}</section>`;
 html+=`<section class="case-block case-gallery"><h3>${escapeHTML(t.galleryTitle)}</h3><p>${escapeHTML(t.galleryIntro)}</p>${e.galleries[id].map((figure,index)=>{const [title,caption,source]=figure[language];return `<figure><a href="assets/evidence/${figure.file}" target="_blank" rel="noopener"><img loading="lazy" src="assets/evidence/${figure.file}" alt="${escapeHTML(title+' — '+caption)}"></a><figcaption><span class="figure-number">${String(index+1).padStart(2,'0')}</span><div><h4>${escapeHTML(title)}</h4><p>${escapeHTML(caption)}</p><small>${escapeHTML(source)}</small><a href="assets/evidence/${figure.file}" target="_blank" rel="noopener">${escapeHTML(t.openImage)}</a></div></figcaption></figure>`;}).join('')}</section>`;
 if(id==='research')html+=`<section class="case-block data-download"><a class="text-link" href="assets/evidence/doppler-comparison.csv" download>${escapeHTML(t.csvLink)}</a><p>${escapeHTML(t.csvNote)}</p></section>`;
 return html;
}
const organizationBrands={"osaka": {"file": "osaka.svg", "name": "The University of Osaka", "url": "https://www.osaka-u.ac.jp/en/", "variant": "inverse"}, "vit": {"file": "vit.webp", "name": "Vellore Institute of Technology", "url": "https://vit.ac.in/", "variant": "inverse"}, "cesc": {"file": "cesc.png", "name": "CESC", "url": "https://www.cesc.co.in/", "variant": ""}, "vitmas": {"file": "vitmas.png", "name": "VIT Mathematical Association", "url": "https://www.linkedin.com/company/vit-mathematical-association-student-chapter", "variant": "seal"}, "nptel": {"file": "nptel.jpg", "name": "NPTEL", "url": "https://nptel.ac.in/", "variant": ""}, "iitkanpur": {"file": "iit-kanpur.png", "name": "Indian Institute of Technology Kanpur", "url": "https://www.iitk.ac.in/", "variant": "seal"}, "sof": {"file": "sof.jpg", "name": "Science Olympiad Foundation (SOF)", "url": "https://sofworld.org/", "variant": ""}, "wiz": {"file": "wiz-spell-bee.png", "name": "WIZ Spell Bee", "url": "https://wizspellbee.com/", "variant": ""}};
function caseBrand(key){
 const b=organizationBrands[key];
 return `<a class="org-logo ${b.variant} case-logo" href="${b.url}" target="_blank" rel="noopener noreferrer" aria-label="${escapeHTML(b.name)} official website"><img src="assets/logos/${b.file}" alt="${escapeHTML(b.name)} logo" loading="lazy"></a>`;
}
function renderCase(id){
 const c=cases[id][language],t=translations[language];
 const block=(heading,body,extra='')=>`<section class="case-block ${extra}"><h3>${escapeHTML(heading)}</h3><p>${escapeHTML(body)}</p></section>`;
 let html=caseBrand(id==='research'?'osaka':'vit')+`<p class="case-kicker">${escapeHTML(c.kicker)}</p><h2 id="case-title">${escapeHTML(c.title)}</h2><p class="case-summary">${escapeHTML(c.summary)}</p><dl class="case-facts">${[['institution',c.institution],['period',c.period],['role',c.role],['tools',c.tools]].map(([label,value])=>`<div><dt>${escapeHTML(t[label])}</dt><dd>${escapeHTML(value)}</dd></div>`).join('')}</dl>`;
 html+=block(t.problem,c.problem);
 html+=`<div class="flow" aria-label="${escapeHTML(t.flowLabel)}">${c.flow.map((step,i)=>`${i?'<i aria-hidden="true">→</i>':''}<span>${escapeHTML(step)}</span>`).join('')}</div>`;
 html+=`<section class="case-block"><h3>${escapeHTML(t.implementation)}</h3><ul>${c.work.map(text=>`<li>${escapeHTML(text)}</li>`).join('')}</ul></section>`;
 html+=block(t.evidence,c.evidence);
 if(id==='research'){
  const d=resultData[$('#channel').value];
  html+=`<section class="case-block"><h3>${escapeHTML(t.dataHeading)}</h3><div class="data-table-wrap"><table><caption>${escapeHTML($('#channel').selectedOptions[0].textContent)} · ${escapeHTML(t.dataCaption)}</caption><thead><tr><th scope="col">${escapeHTML(t.tableSNR)}</th><th scope="col">${escapeHTML(t.rawLS)} / Hz</th><th scope="col">${escapeHTML(t.rawWLS)} / Hz</th></tr></thead><tbody>${snr.map((v,i)=>`<tr><th scope="row">${v}</th><td>${d.ls[i].toFixed(3)}</td><td>${d.wls[i].toFixed(3)}</td></tr>`).join('')}</tbody></table></div></section>`;
 }
 html+=renderEvidence(id);
 html+=block(t.limitations,c.limits);html+=block(t.takeaway,c.takeaway,'case-highlight');
 $('#case-content').innerHTML=html;
}
function closeCase(){currentCase=null;$('#case-dialog').close();document.body.style.overflow='';}
document.querySelectorAll('[data-case]').forEach(button=>button.addEventListener('click',()=>{currentCase=button.dataset.case;renderCase(currentCase);$('#case-dialog').showModal();$('#case-dialog').scrollTop=0;document.body.style.overflow='hidden';}));
$('#close-dialog').addEventListener('click',closeCase);$('#close-bottom').addEventListener('click',closeCase);
$('#case-dialog').addEventListener('cancel',event=>{event.preventDefault();closeCase();});
$('#case-dialog').addEventListener('click',event=>{if(event.target===event.currentTarget){const r=event.currentTarget.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeCase();}});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{
 document.querySelectorAll('[data-filter]').forEach(other=>other.setAttribute('aria-pressed',String(other===button)));
 document.querySelectorAll('.project').forEach(project=>project.hidden=button.dataset.filter!=='all'&&project.dataset.category!==button.dataset.filter);
}));
document.querySelectorAll('[data-language-select]').forEach(select=>select.addEventListener('change',()=>setLanguage(select.value)));$('#channel').addEventListener('change',renderChart);
$('.menu-toggle').addEventListener('click',()=>{const open=$('.menu-toggle').getAttribute('aria-expanded')!=='true';$('.menu-toggle').setAttribute('aria-expanded',String(open));$('#navigation').classList.toggle('open',open);});
$('#navigation').querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');}));
$('#copy-email').addEventListener('click',async()=>{try{await navigator.clipboard.writeText('someshmridha.official@gmail.com');$('#copy-status').textContent=translations[language].copied;}catch{$('#copy-status').textContent=translations[language].copyFallback;}});
const wave=Array.from({length:249},(_,i)=>{const x=52+i*2,y=480-Math.sin(i*.26+i*i*.0007)*Math.exp(-Math.pow((i-124)/112,2))*17;return `${i?'L':'M'}${x.toFixed(1)} ${y.toFixed(2)}`;}).join(' ');$('#hero-wave').setAttribute('d',wave);
let storedLanguage;try{storedLanguage=localStorage.getItem('somesh-portfolio-language');}catch{}
setLanguage(supportedLanguages.includes(storedLanguage)?storedLanguage:'en');
